CREATE OR REPLACE FUNCTION private.battle31_rules() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT '{"version":"battle-31/1","turnMs":15000,"introMs":1200,"holdMs":4000,"normalTurns":6,"maxTurns":8,"maxRounds":12,"lossLimit":4}'::jsonb
$$;
CREATE OR REPLACE FUNCTION private.battle31_score(hand jsonb) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE ranks integer[]; answer numeric;
BEGIN
 IF jsonb_typeof(hand)<>'array' OR jsonb_array_length(hand)<>3 THEN RAISE EXCEPTION 'battle31:invalid_hand';END IF;
 SELECT array_agg((x::text)::int%8) INTO ranks FROM jsonb_array_elements(hand) x;
 IF ranks[1]=ranks[2] AND ranks[2]=ranks[3] THEN RETURN CASE WHEN ranks[1]=7 THEN 32 ELSE 30.5 END;END IF;
 SELECT max(total) INTO answer FROM (SELECT sum(CASE WHEN n%8=7 THEN 11 WHEN n%8>=3 THEN 10 ELSE n%8+7 END) total FROM (SELECT (x::text)::int n FROM jsonb_array_elements(hand) x) c GROUP BY n/8) totals;
 RETURN answer;
END $$;
CREATE OR REPLACE FUNCTION private.battle31_shuffle() RETURNS jsonb LANGUAGE plpgsql VOLATILE SET search_path='' AS $$
DECLARE cards integer[]:=ARRAY(SELECT generate_series(0,31));i int;j int;b int;t int;
BEGIN
 FOR i IN REVERSE 32..2 LOOP
  LOOP b:=get_byte(extensions.gen_random_bytes(1),0);EXIT WHEN b<256-(256%i);END LOOP;
  j:=1+b%i;t:=cards[i];cards[i]:=cards[j];cards[j]:=t;
 END LOOP;
 RETURN to_jsonb(cards);
END $$;
CREATE OR REPLACE FUNCTION private.battle31_complete(s jsonb,reason text,at_ms bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE ranks jsonb;
BEGIN
 SELECT jsonb_object_agg(p->>'id',CASE WHEN reason='aborted' THEN 0 ELSE -(s->'losses'->>(i-1)::int)::int END) INTO ranks FROM jsonb_array_elements(s->'players') WITH ORDINALITY x(p,i);
 RETURN s||jsonb_build_object('phase','complete','deadline',0,'ranks',ranks,'outcome',reason,'event',jsonb_build_object('label',CASE WHEN reason='aborted' THEN 'Match aborted' WHEN (s->'losses'->>0)::int=(s->'losses'->>1)::int THEN 'Match drawn' ELSE 'Match complete' END));
END $$;
CREATE OR REPLACE FUNCTION private.battle31_resolve(s jsonb,reason text,at_ms bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE a numeric:=private.battle31_score(s->'hands'->0);b numeric:=private.battle31_score(s->'hands'->1);loser int;result jsonb;
BEGIN
 IF a<>b THEN loser:=CASE WHEN a<b THEN 0 ELSE 1 END;s:=jsonb_set(s,ARRAY['losses',loser::text],to_jsonb((s->'losses'->>loser)::int+1));END IF;
 result:=jsonb_build_object('round',s->'stage','hands',s->'hands','values',jsonb_build_array(a,b),'loser',loser,'reason',reason,'losses',s->'losses');
 s:=s||jsonb_build_object('result',result,'results',coalesce(s->'results','[]'::jsonb)||jsonb_build_array(result),'event',jsonb_build_object('label',CASE WHEN loser IS NULL THEN 'Round drawn' ELSE (s->'players'->loser->>'name')||' loses a life' END));
 IF greatest((s->'losses'->>0)::int,(s->'losses'->>1)::int)>=4 OR (s->>'stage')::int>=12 THEN RETURN private.battle31_complete(s,'completed',at_ms);END IF;
 RETURN s||jsonb_build_object('phase','round_result','deadline',at_ms+4000);
END $$;
CREATE OR REPLACE FUNCTION private.battle31_deal(s jsonb,at_ms bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE d jsonb:=private.battle31_shuffle();first_i int;hands jsonb;round_i int:=coalesce((s->>'stage')::int,1);
BEGIN
 IF jsonb_array_length(s->'players')<>2 OR s#>>'{rules,version}'<>'battle-31/1' THEN RAISE EXCEPTION 'battle31:configuration';END IF;
 IF NOT s?'firstActor' THEN s:=s||jsonb_build_object('firstActor',get_byte(extensions.gen_random_bytes(1),0)%2,'losses','[0,0]'::jsonb,'results','[]'::jsonb);END IF;
 first_i:=((s->>'firstActor')::int+round_i-1)%2;
 hands:=CASE WHEN first_i=0 THEN jsonb_build_array(jsonb_build_array(d->0,d->2,d->4),jsonb_build_array(d->1,d->3,d->5)) ELSE jsonb_build_array(jsonb_build_array(d->1,d->3,d->5),jsonb_build_array(d->0,d->2,d->4)) END;
 s:=s||jsonb_build_object('hands',hands,'center',jsonb_build_array(d->6,d->7,d->8),'known','[[],[]]'::jsonb,'turnIndex',first_i,'turn',1,'closing',false,'phase','intro','deadline',at_ms+1200,'result',NULL,'dealId',gen_random_uuid(),'event',jsonb_build_object('label','Round '||round_i));
 -- Only nine cards are used; the other 23 are never projected or drawn this round.
 RETURN s;
END $$;
CREATE OR REPLACE FUNCTION private.battle31_reduce(s jsonb,action text,items integer[],at_ms bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE actor int:=(s->>'turnIndex')::int;opponent int:=1-actor;turn_i int:=(s->>'turn')::int;hand jsonb:=s->'hands'->actor;center jsonb:=s->'center';old_hand jsonb:=hand;own_slot int;center_slot int;known jsonb;
BEGIN
 IF s#>>'{rules,version}'<>'battle-31/1' OR s->>'phase'='complete' THEN RAISE EXCEPTION 'battle31:phase';END IF;
 IF action='resign' THEN
  IF cardinality(items)<>1 OR items[1] NOT IN(0,1) THEN RAISE EXCEPTION 'battle31:invalid_command';END IF;
  RETURN private.battle31_complete(jsonb_set(s,ARRAY['losses',items[1]::text],'4'),'resigned',at_ms);
 END IF;
 IF action='tick' THEN
  IF at_ms<(s->>'deadline')::bigint THEN RETURN s;END IF;
  IF s->>'phase'='intro' THEN
   IF greatest(private.battle31_score(s->'hands'->0),private.battle31_score(s->'hands'->1))>=31 THEN RETURN private.battle31_resolve(s,'initial_special',at_ms);END IF;
   RETURN s||jsonb_build_object('phase','playing','deadline',at_ms+15000,'event',jsonb_build_object('label','Your turn'));
  ELSIF s->>'phase'='round_result' THEN RETURN private.battle31_deal(s||jsonb_build_object('stage',(s->>'stage')::int+1),at_ms);
  END IF;
  action:='pass';
 ELSIF at_ms>=(s->>'deadline')::bigint THEN RAISE EXCEPTION 'battle31:deadline';END IF;
 IF s->>'phase'<>'playing' THEN RAISE EXCEPTION 'battle31:phase';END IF;
 IF action='swap' THEN
  IF cardinality(items) IS DISTINCT FROM 2 OR items[1]=items[2] THEN RAISE EXCEPTION 'battle31:invalid_command';END IF;
  SELECT i-1 INTO own_slot FROM jsonb_array_elements_text(hand) WITH ORDINALITY x(card,i) WHERE card::int=items[1];
  SELECT i-1 INTO center_slot FROM jsonb_array_elements_text(center) WITH ORDINALITY x(card,i) WHERE card::int=items[2];
  IF own_slot IS NULL OR center_slot IS NULL THEN RAISE EXCEPTION 'battle31:stale_cards';END IF;
  hand:=jsonb_set(hand,ARRAY[own_slot::text],to_jsonb(items[2]));center:=jsonb_set(center,ARRAY[center_slot::text],to_jsonb(items[1]));
 ELSIF action='take_pot' THEN hand:=center;center:=old_hand;
 ELSIF action<>'pass' THEN RAISE EXCEPTION 'battle31:invalid_action';END IF;
 IF action<>'swap' AND cardinality(items)>0 THEN RAISE EXCEPTION 'battle31:invalid_command';END IF;
 -- Track only publicly witnessed cards held by each seat. The bot gets this memory, never hidden hands.
 SELECT coalesce(jsonb_agg(card ORDER BY card),'[]') INTO known FROM (SELECT DISTINCT card FROM (SELECT value card FROM jsonb_array_elements(s->'known'->actor) UNION SELECT value FROM jsonb_array_elements(hand) WHERE NOT old_hand @> jsonb_build_array(value)) seen WHERE hand @> jsonb_build_array(card)) k;
 s:=jsonb_set(jsonb_set(s,ARRAY['hands',actor::text],hand),ARRAY['known',actor::text],known)||jsonb_build_object('center',center,'event',jsonb_build_object('label',CASE action WHEN 'swap' THEN 'Card exchanged' WHEN 'take_pot' THEN 'All three exchanged' ELSE CASE WHEN (s->>'closing')::boolean OR turn_i>=7 THEN 'Stand' ELSE 'Opponent’s last turn' END END));
 IF greatest(private.battle31_score(s->'hands'->0),private.battle31_score(s->'hands'->1))>=31 THEN RETURN private.battle31_resolve(s,'special',at_ms);END IF;
 IF (s->>'closing')::boolean OR turn_i=8 THEN RETURN private.battle31_resolve(s,CASE WHEN (s->>'closing')::boolean THEN 'pass' ELSE 'turn_limit' END,at_ms);END IF;
 s:=s||jsonb_build_object('turn',turn_i+1,'turnIndex',opponent,'closing',action='pass' AND turn_i<=6,'deadline',at_ms+15000);
 IF turn_i=6 AND action<>'pass' THEN s:=s||jsonb_build_object('event',jsonb_build_object('label','Last turn each'));END IF;
 RETURN s;
END $$;
CREATE OR REPLACE FUNCTION private.battle31_visible(s jsonb,viewer uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
DECLARE hands jsonb:='[]';values_i jsonb:='[]';i int;visible boolean;
BEGIN
 FOR i IN 0..1 LOOP
  visible:=s->>'phase' IN('round_result','complete') OR s->'players'->i->>'id'=viewer::text;
  hands:=hands||jsonb_build_array(CASE WHEN visible THEN s->'hands'->i ELSE '[null,null,null]'::jsonb END);
  values_i:=values_i||jsonb_build_array(CASE WHEN visible THEN to_jsonb(private.battle31_score(s->'hands'->i)) ELSE 'null'::jsonb END);
 END LOOP;
 RETURN (s-ARRAY['hands','score','scores','stages'])||jsonb_build_object('hands',hands,'values',values_i,'activePlayerId',s->'players'->(s->>'turnIndex')::int->>'id');
END $$;

-- Additive authority candidate. Both release gates start CLOSED.
SET LOCAL lock_timeout = '100ms';
SET LOCAL statement_timeout = '10s';
CREATE TABLE private.battle31_release (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), enabled boolean NOT NULL DEFAULT false, admission_enabled boolean NOT NULL DEFAULT false);
INSERT INTO private.battle31_release DEFAULT VALUES;
ALTER TABLE private.battle31_release ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.battle31_release FROM PUBLIC,anon,authenticated,service_role;

CREATE TABLE private.battle31_matches (
 dealer_game_id uuid PRIMARY KEY,
 game_id uuid NOT NULL, round_id uuid NOT NULL,
 state jsonb NOT NULL, revision bigint NOT NULL DEFAULT 0, stake integer NOT NULL CHECK(stake>0),
 settlement jsonb, finished boolean NOT NULL DEFAULT false, paused_at bigint, bot_due_at bigint,

 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX battle31_matches_session ON private.battle31_matches(game_id);
CREATE INDEX battle31_matches_pending ON private.battle31_matches(((state->>'deadline')::bigint)) WHERE NOT finished AND settlement IS NULL;

CREATE TABLE private.battle31_requests (
 dealer_game_id uuid NOT NULL REFERENCES private.battle31_matches(dealer_game_id) ON DELETE CASCADE,
 request_id uuid NOT NULL, actor uuid NOT NULL, command jsonb NOT NULL,
 PRIMARY KEY(dealer_game_id,request_id)
);
CREATE TABLE private.battle31_history (
 dealer_game_id uuid NOT NULL REFERENCES private.battle31_matches(dealer_game_id) ON DELETE CASCADE,
 revision bigint NOT NULL, frame jsonb NOT NULL, PRIMARY KEY(dealer_game_id,revision)
);
ALTER TABLE private.battle31_matches ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.battle31_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.battle31_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.battle31_matches,private.battle31_requests,private.battle31_history FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.battle31_revisions (
 dealer_game_id uuid PRIMARY KEY REFERENCES private.battle31_matches(dealer_game_id) ON DELETE CASCADE,
 game_id uuid NOT NULL, revision bigint NOT NULL
);
ALTER TABLE public.battle31_revisions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.battle31_revisions FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public.battle31_revisions TO authenticated;
CREATE POLICY battle31_member_read ON public.battle31_revisions FOR SELECT TO authenticated
 USING(EXISTS(SELECT 1 FROM public.players p WHERE p.game_id=battle31_revisions.game_id AND p.user_id=(SELECT auth.uid()) AND p.status<>'left'));

-- Same approved-account eligibility as Run21; independent game release gate.
CREATE OR REPLACE FUNCTION private.battle31_actor_allowed(actor uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT actor IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=actor AND is_active)
  AND EXISTS(SELECT 1 FROM private.battle31_release WHERE singleton AND enabled)
$function$
;
CREATE OR REPLACE FUNCTION public.battle31_capabilities(p_session_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); allowed boolean:=private.battle31_actor_allowed(actor);
BEGIN
 allowed:=allowed AND EXISTS(SELECT 1 FROM private.battle31_release WHERE singleton AND admission_enabled);
 IF p_session_id IS NOT NULL THEN
  allowed:=allowed AND EXISTS(SELECT 1 FROM public.games WHERE id=p_session_id)
   AND EXISTS(SELECT 1 FROM public.players WHERE game_id=p_session_id AND user_id=actor AND status<>'left')
   AND NOT EXISTS(SELECT 1 FROM public.players WHERE game_id=p_session_id AND status<>'left' AND NOT is_bot AND NOT private.battle31_actor_allowed(user_id));
 END IF;
 RETURN jsonb_build_object('version',2,'enabled',allowed,'user_id',actor,'session_id',p_session_id,'fake_money_only',false);
END $function$
;
CREATE OR REPLACE FUNCTION private.battle31_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 INSERT INTO public.battle31_revisions VALUES(NEW.dealer_game_id,NEW.game_id,NEW.revision)
 ON CONFLICT(dealer_game_id) DO UPDATE SET revision=EXCLUDED.revision;
 INSERT INTO private.battle31_history VALUES(NEW.dealer_game_id,NEW.revision,jsonb_build_object('phase',NEW.state->'phase','dealId',NEW.state->'dealId','turn',NEW.state->'turn','event',NEW.state->'event')) ON CONFLICT DO NOTHING;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.battle31_snapshot(p_dealer_game_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m private.battle31_matches; viewer uuid; paused boolean; balances jsonb; batch public.gameplay_transfer_batches; result_id uuid;
BEGIN
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer_game_id;
 SELECT id INTO viewer FROM public.players WHERE game_id=m.game_id AND user_id=auth.uid() AND (status<>'left' OR m.finished) AND NOT is_bot;
 IF viewer IS NULL OR NOT private.battle31_actor_allowed(auth.uid()) THEN RAISE EXCEPTION 'battle31:membership_required' USING ERRCODE='42501'; END IF;
 SELECT is_paused INTO paused FROM public.games WHERE id=m.game_id;
 IF m.settlement IS NOT NULL THEN
  SELECT jsonb_object_agg(player_id::text,chips) INTO balances FROM public.session_player_snapshots WHERE dealer_game_id=p_dealer_game_id;
 ELSE SELECT jsonb_object_agg(id::text,chips) INTO balances FROM public.players WHERE game_id=m.game_id;END IF;
 SELECT * INTO batch FROM public.gameplay_transfer_batches WHERE dealer_game_id=p_dealer_game_id ORDER BY cursor DESC LIMIT 1;
 SELECT id INTO result_id FROM public.game_results WHERE dealer_game_id=p_dealer_game_id AND settlement_key='battle31_terminal';
 RETURN private.battle31_visible(m.state,viewer)||jsonb_build_object('revision',m.revision,'stake',m.stake,'viewerId',viewer,
  'canAct',NOT coalesce(paused,false) AND m.state->>'phase'='playing' AND m.state->'players'->(m.state->>'turnIndex')::integer->>'id'=viewer::text,
  'serverAt',floor(extract(epoch FROM clock_timestamp())*1000),'settlement',m.settlement,'paused',coalesce(paused,false),'finished',m.finished,'pausedAt',m.paused_at,'financial',jsonb_build_object('balances',coalesce(balances,'{}'::jsonb),'resultId',result_id,'batch',CASE WHEN batch.id IS NOT NULL THEN to_jsonb(batch) ELSE NULL END))
;
END $function$
;
CREATE OR REPLACE FUNCTION private.battle31_settle(p_dealer_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m private.battle31_matches; g public.games; winners uuid[]; win_count integer; total integer; deltas jsonb; transfers jsonb:='[]';
 result_id uuid; player jsonb; winner uuid; loser uuid; amount integer; changes jsonb:='{}'; allocated integer;
BEGIN
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer_game_id FOR UPDATE;
 IF m.settlement IS NOT NULL THEN RETURN; END IF;
 SELECT * INTO STRICT g FROM public.games WHERE id=m.game_id FOR UPDATE;
 IF g.game_type IS DISTINCT FROM 'battle-31' OR g.current_game_uuid IS DISTINCT FROM m.dealer_game_id OR g.status<>'in_progress' OR g.is_paused
  OR m.state->>'phase'<>'complete' OR (SELECT count(*) FROM jsonb_object_keys(m.state->'ranks'))<>jsonb_array_length(m.state->'players') THEN RAISE EXCEPTION 'battle31:not_terminal'; END IF;
 SELECT array_agg(key::uuid ORDER BY key) INTO winners FROM jsonb_each_text(m.state->'ranks') WHERE value::integer=(SELECT max(value::integer) FROM jsonb_each_text(m.state->'ranks'));
 win_count:=cardinality(winners);total:=(jsonb_array_length(m.state->'players')-win_count)*m.stake;
 deltas:=private.split_whole_chips_clockwise(m.game_id,winners,total,g.dealer_position);
 FOR player IN SELECT value FROM jsonb_array_elements(m.state->'players') LOOP
  loser:=(player->>'id')::uuid;
  IF NOT loser=ANY(winners) THEN changes:=changes||jsonb_build_object(loser::text,-m.stake); END IF;
 END LOOP;
 changes:=changes||deltas;
 -- Existing signed session chip accounting and transfer journal; no alternate ledger.
 -- Allocate each loser's stake across winners according to the canonical split.
 FOR player IN SELECT value FROM jsonb_array_elements(m.state->'players') LOOP
  loser:=(player->>'id')::uuid;IF loser=ANY(winners) THEN CONTINUE; END IF;allocated:=m.stake;
  FOREACH winner IN ARRAY winners LOOP
   amount:=least(allocated,(deltas->>winner::text)::integer);
   IF amount>0 THEN transfers:=transfers||jsonb_build_array(jsonb_build_object('from',jsonb_build_object('kind','player','playerId',loser),'to',jsonb_build_object('kind','player','playerId',winner),'amount',amount));
    deltas:=jsonb_set(deltas,ARRAY[winner::text],to_jsonb((deltas->>winner::text)::integer-amount));allocated:=allocated-amount;END IF;
  END LOOP;
  IF allocated<>0 THEN RAISE EXCEPTION 'battle31:unbalanced_settlement'; END IF;
 END LOOP;
 INSERT INTO public.game_results(game_id,dealer_game_id,hand_number,settlement_key,game_type,winner_player_id,winner_username,winning_hand_description,pot_won,player_chip_changes,is_chopped)
 VALUES(m.game_id,m.dealer_game_id,1,'battle31_terminal','battle-31',CASE WHEN win_count=1 THEN winners[1] END,
  CASE WHEN win_count>1 THEN 'Tie' ELSE (SELECT p->>'name' FROM jsonb_array_elements(m.state->'players') p WHERE p->>'id'=winners[1]::text) END,
  'Battle 31: '||(m.state->'ranks')::text,total,changes,win_count>1) RETURNING id INTO result_id;
 IF jsonb_array_length(transfers)>0 THEN PERFORM public.settle_gameplay_chip_transfers(m.game_id,transfers,'win'); END IF;
 UPDATE public.rounds SET status='completed',decision_deadline=NULL,current_turn_position=NULL WHERE id=m.round_id;
 INSERT INTO public.session_player_snapshots(game_id,dealer_game_id,player_id,user_id,username,chips,is_bot,hand_number)
 SELECT p.game_id,m.dealer_game_id,p.id,p.user_id,coalesce(pr.username,'Player'),p.chips,p.is_bot,1 FROM public.players p LEFT JOIN public.profiles pr ON pr.id=p.user_id WHERE p.game_id=m.game_id
 ON CONFLICT(game_id,dealer_game_id,hand_number,player_id) DO UPDATE SET chips=EXCLUDED.chips,created_at=clock_timestamp();
 UPDATE private.battle31_matches SET settlement=changes,revision=revision+1,state=state||jsonb_build_object('terminal',jsonb_build_object('resultId',result_id,'winnerIds',to_jsonb(winners),'startedAt',floor(extract(epoch FROM clock_timestamp())*1000)::bigint,'deadline',floor(extract(epoch FROM clock_timestamp())*1000)::bigint+3000,'outcome',m.state->>'outcome')) WHERE dealer_game_id=m.dealer_game_id;
 UPDATE public.games SET status=CASE WHEN pending_session_end THEN 'session_ended' ELSE 'game_over' END,
  session_ended_at=CASE WHEN pending_session_end THEN clock_timestamp() ELSE session_ended_at END,pending_session_end=false,
  game_over_at=clock_timestamp(),last_round_result='Battle 31 complete',awaiting_next_round=false WHERE id=m.game_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.battle31_configure(p_game_id uuid, p_dealer_player_id uuid, p_expected_dealer_position integer, p_game_type text, p_config jsonb, p_expected_config_deadline timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE g public.games; d public.players; dg public.dealer_games; r uuid:=gen_random_uuid(); actor uuid:=auth.uid();
 claim private.dealer_game_setup_commits; hash text; stake_i integer; people jsonb; s jsonb; result jsonb; setup_players jsonb;
BEGIN
 IF NOT private.battle31_actor_allowed(actor) OR p_game_type IS DISTINCT FROM 'battle-31' THEN RAISE EXCEPTION 'battle31:release_closed' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT g FROM public.games WHERE id=p_game_id FOR UPDATE;
 SELECT * INTO STRICT d FROM public.players WHERE id=p_dealer_player_id AND game_id=g.id;
 IF d.user_id IS DISTINCT FROM actor OR d.is_bot THEN RAISE EXCEPTION 'battle31:dealer_required' USING ERRCODE='42501';END IF;

 IF coalesce(p_config->>'ante_amount','') !~ '^[1-9][0-9]{0,3}$' OR p_expected_config_deadline IS NULL THEN RAISE EXCEPTION 'battle31:config';END IF;stake_i:=(p_config->>'ante_amount')::integer;
 hash:=md5(jsonb_build_array(p_game_id,p_dealer_player_id,p_expected_dealer_position,p_config,p_expected_config_deadline)::text);
 SELECT * INTO claim FROM private.dealer_game_setup_commits WHERE game_id=g.id AND expected_config_deadline=p_expected_config_deadline AND expected_dealer_position=p_expected_dealer_position;
 IF FOUND THEN
  IF claim.request_hash<>hash THEN RAISE EXCEPTION 'battle31:setup_replay_conflict';END IF;
  IF g.current_game_uuid IS DISTINCT FROM claim.dealer_game_id THEN RAISE EXCEPTION 'battle31:setup_retired';END IF;
  RETURN claim.result||'{"outcome":"already_configured","deduped":true}'::jsonb;
 END IF;
 -- Admission controls creation only; existing setup retries and match authority remain live.
 IF NOT EXISTS(SELECT 1 FROM private.battle31_release WHERE singleton AND admission_enabled) THEN RAISE EXCEPTION 'battle31:admission_closed' USING ERRCODE='42501';END IF;
 IF d.user_id<>actor OR d.is_bot OR d.sitting_out OR d.status<>'active' OR d.position<>p_expected_dealer_position
 OR g.dealer_position IS DISTINCT FROM p_expected_dealer_position OR g.status NOT IN ('game_selection','configuring')
 OR g.config_deadline IS DISTINCT FROM p_expected_config_deadline OR clock_timestamp()>g.config_deadline OR g.is_paused OR g.pending_session_end THEN RAISE EXCEPTION 'battle31:setup_identity';END IF;
 PERFORM 1 FROM public.players WHERE game_id=g.id ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.players WHERE game_id=g.id AND status<>'left' AND NOT is_bot AND NOT private.battle31_actor_allowed(user_id)) THEN RAISE EXCEPTION 'battle31:tester_required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.players WHERE game_id=g.id AND status='active' AND NOT sitting_out AND NOT waiting AND position IS NOT NULL AND NOT is_bot) THEN RAISE EXCEPTION 'battle31:human_required';END IF;
 SELECT jsonb_agg(jsonb_build_object('id',p.id,'userId',p.user_id,'name',coalesce(pr.username,'Player'),'seat',p.position,'isBot',p.is_bot)
 ORDER BY CASE WHEN p.position<g.dealer_position THEN 0 ELSE 1 END,p.position DESC,p.id) INTO people
 FROM public.players p LEFT JOIN public.profiles pr ON pr.id=p.user_id WHERE p.game_id=g.id AND p.status='active' AND NOT p.sitting_out AND NOT p.waiting AND p.position IS NOT NULL;
 IF coalesce(jsonb_array_length(people),0) <>2 THEN RAISE EXCEPTION 'battle31:player_count';END IF;
 IF coalesce(g.pot,0)<>0 THEN RAISE EXCEPTION 'battle31:unfinished_pot';END IF;
 -- Established setup-authority handoff flags, scoped to this validated RPC.
 PERFORM set_config('app.cribbage_authoritative_write','on',true);
 PERFORM set_config('app.gin_rummy_authoritative_write','on',true);
 PERFORM set_config('app.three_five_seven_authoritative_write','on',true);
 PERFORM set_config('app.yahtzee_authoritative_write','on',true);
 IF g.game_type='farkle' THEN PERFORM private.farkle_claim_v1(g.id,g.current_game_uuid,NULL,'configure');END IF;
 INSERT INTO public.dealer_games(session_id,dealer_user_id,game_type,config) VALUES(g.id,actor,'battle-31',jsonb_build_object('ante_amount',stake_i,'rules',private.battle31_rules())) RETURNING * INTO dg;
 UPDATE public.players SET ante_decision=CASE WHEN id=p_dealer_player_id THEN 'ante_up' ELSE NULL END,current_decision=NULL,decision_locked=false,auto_fold=false WHERE game_id=g.id AND id IN(SELECT (p->>'id')::uuid FROM jsonb_array_elements(people) p);
 UPDATE public.games SET game_type='battle-31',current_game_uuid=dg.id,config_complete=true,config_deadline=NULL,ante_decision_deadline=clock_timestamp()+make_interval(secs=>greatest(1,coalesce(g.ante_decision_timer_seconds,30))),status='ante_decision',ante_amount=stake_i,current_round=NULL,total_hands=0,replay_contract_version=NULL,all_decisions_in=false,all_decisions_in_round_id=NULL WHERE id=g.id RETURNING * INTO g;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY position) INTO setup_players FROM public.players p WHERE game_id=g.id;
 result:=jsonb_build_object('outcome','configured','deduped',false,'setup_identity',jsonb_build_object('game_id',g.id,'dealer_position',p_expected_dealer_position,'expected_config_deadline',p_expected_config_deadline),'game',to_jsonb(g),'dealer_game',to_jsonb(dg),'players',setup_players);
 INSERT INTO private.dealer_game_setup_commits(game_id,expected_config_deadline,expected_dealer_position,request_hash,dealer_game_id,result) VALUES(g.id,p_expected_config_deadline,p_expected_dealer_position,hash,dg.id,result);
 RETURN result;
END $function$
;
CREATE OR REPLACE FUNCTION private.battle31_finish_postgame(p_dealer_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m private.battle31_matches; g public.games; positions integer[]; next_seat integer; target text; winner uuid; make_take boolean;
BEGIN
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer_game_id;
 PERFORM 1 FROM public.rounds WHERE id=m.round_id FOR UPDATE;
 SELECT * INTO STRICT g FROM public.games WHERE id=m.game_id FOR UPDATE;
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer_game_id FOR UPDATE;
 IF m.settlement IS NULL THEN RAISE EXCEPTION 'battle31:close_denied' USING ERRCODE='42501';END IF;
 IF m.finished THEN RETURN;END IF;
 IF coalesce((m.state#>>'{terminal,deadline}')::bigint,0)>floor(extract(epoch FROM clock_timestamp())*1000) THEN RETURN;END IF;
 IF g.current_game_uuid IS DISTINCT FROM m.dealer_game_id OR g.game_type IS DISTINCT FROM 'battle-31' OR g.status NOT IN ('game_over','session_ended') THEN RAISE EXCEPTION 'battle31:close_identity';END IF;
 IF g.status<>'session_ended' THEN
  PERFORM 1 FROM public.players WHERE game_id=m.game_id ORDER BY id FOR UPDATE;
  UPDATE public.players SET status=CASE WHEN stand_up_next_hand THEN 'left' ELSE status END,
   sitting_out=CASE WHEN stand_up_next_hand OR sit_out_next_hand THEN true WHEN waiting THEN false ELSE sitting_out END,
   waiting=false,stand_up_next_hand=false,sit_out_next_hand=false,auto_fold=false,auto_play_stop_round_id=NULL,
   current_decision=NULL,decision_locked=false,pre_fold=false,pre_stay=false,ante_decision=NULL,auto_ante=false,auto_ante_runback=false WHERE game_id=m.game_id;
  IF g.pending_session_end THEN target:='session_ended';
  ELSIF (SELECT count(*) FROM public.players WHERE game_id=m.game_id AND status NOT IN ('left','observer') AND NOT sitting_out AND position IS NOT NULL)<2 THEN
   PERFORM private.resolve_postgame_participation(m.game_id,clock_timestamp());SELECT status INTO target FROM public.games WHERE id=m.game_id;
  ELSE
   SELECT array_agg(position ORDER BY position DESC) INTO positions FROM public.players WHERE game_id=m.game_id AND status NOT IN ('left','observer') AND NOT sitting_out AND position IS NOT NULL AND NOT is_bot;
   SELECT coalesce((value->>'enabled')::boolean,false) INTO make_take FROM public.system_settings WHERE key='make_it_take_it';
   IF coalesce(make_take,false) THEN
    SELECT winner_player_id INTO winner FROM public.game_results WHERE dealer_game_id=m.dealer_game_id AND settlement_key='battle31_terminal';
    SELECT position INTO next_seat FROM public.players WHERE id=winner AND game_id=m.game_id AND NOT is_bot AND NOT sitting_out AND status NOT IN ('left','observer') AND position IS NOT NULL;
    IF next_seat IS NULL THEN IF cardinality(positions)=1 THEN next_seat:=positions[1];ELSE target:='dealer_selection';END IF;END IF;
   END IF;
   IF target IS NULL THEN
    IF next_seat IS NULL THEN SELECT max(p) INTO next_seat FROM unnest(positions) p WHERE p<g.dealer_position;next_seat:=coalesce(next_seat,positions[1]);END IF;
    target:=CASE WHEN next_seat IS NULL THEN 'dealer_selection' ELSE 'game_selection' END;
   END IF;
  END IF;
  UPDATE public.games SET status=target,game_type=CASE WHEN target='session_ended' THEN game_type END,
   current_game_uuid=NULL,config_complete=false,current_round=NULL,total_hands=0,all_decisions_in=false,all_decisions_in_round_id=NULL,
   last_round_result=NULL,awaiting_next_round=false,next_round_number=NULL,game_over_at=NULL,pot=0,
   ante_decision_deadline=NULL,buck_position=NULL,is_first_hand=false,dealer_selection_state=NULL,
   dealer_position=coalesce(next_seat,dealer_position),config_deadline=CASE WHEN target='game_selection' THEN clock_timestamp()+make_interval(secs=>greatest(1,game_setup_timer_seconds)) END,
   pending_session_end=CASE WHEN target='session_ended' THEN false ELSE pending_session_end END,
   session_ended_at=CASE WHEN target='session_ended' THEN coalesce(session_ended_at,clock_timestamp()) ELSE session_ended_at END WHERE id=m.game_id;
 END IF;
 UPDATE private.battle31_matches SET finished=true,revision=revision+1 WHERE dealer_game_id=m.dealer_game_id;
END $function$
;
CREATE OR REPLACE FUNCTION public.battle31_close(p_dealer_game_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE session uuid; BEGIN SELECT game_id INTO STRICT session FROM private.battle31_matches WHERE dealer_game_id=p_dealer_game_id;
IF NOT private.battle31_actor_allowed(auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.players WHERE game_id=session AND user_id=auth.uid() AND status<>'left' AND NOT is_bot) THEN RAISE EXCEPTION 'battle31:close_denied' USING ERRCODE='42501';END IF;
PERFORM private.battle31_finish_postgame(p_dealer_game_id);END $function$
;
CREATE OR REPLACE FUNCTION private.battle31_pause()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE at_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000);
BEGIN
 IF NEW.game_type IS DISTINCT FROM 'battle-31' OR NEW.is_paused IS NOT DISTINCT FROM OLD.is_paused THEN RETURN NEW;END IF;
 IF NEW.is_paused THEN UPDATE private.battle31_matches SET paused_at=at_ms,revision=revision+1 WHERE dealer_game_id=NEW.current_game_uuid AND settlement IS NULL;
 ELSE UPDATE private.battle31_matches SET state=state||jsonb_build_object('deadline',(state->>'deadline')::bigint+at_ms-paused_at)||CASE WHEN state ? 'startedAt' THEN jsonb_build_object('startedAt',(state->>'startedAt')::bigint+at_ms-paused_at) ELSE '{}'::jsonb END,paused_at=NULL,revision=revision+1 WHERE dealer_game_id=NEW.current_game_uuid AND paused_at IS NOT NULL AND settlement IS NULL;END IF;
 RETURN NEW;
END $function$
;

-- All human, bot and timeout transitions share this locking/receipt/settlement owner.
CREATE OR REPLACE FUNCTION private.battle31_commit(p_dealer uuid,p_request uuid,p_revision bigint,p_player uuid,p_action text,p_items integer[] DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m private.battle31_matches;g public.games;prior private.battle31_requests;actor_i int;at_ms bigint;cmd jsonb:=jsonb_build_object('revision',p_revision,'action',p_action,'items',p_items);
BEGIN
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer;
 PERFORM 1 FROM public.rounds WHERE id=m.round_id FOR UPDATE;
 SELECT * INTO STRICT g FROM public.games WHERE id=m.game_id FOR UPDATE;
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer FOR UPDATE;
 SELECT i-1 INTO actor_i FROM jsonb_array_elements(m.state->'players') WITH ORDINALITY x(p,i) WHERE p->>'id'=p_player::text;
 IF actor_i IS NULL OR p_request IS NULL OR p_revision IS NULL THEN RAISE EXCEPTION 'battle31:participant_required' USING ERRCODE='42501';END IF;
 SELECT * INTO prior FROM private.battle31_requests WHERE dealer_game_id=p_dealer AND request_id=p_request;
 IF FOUND THEN IF prior.actor<>p_player OR prior.command<>cmd THEN RAISE EXCEPTION 'battle31:replay_conflict';END IF;RETURN;END IF;
 IF g.current_game_uuid IS DISTINCT FROM p_dealer OR g.game_type IS DISTINCT FROM 'battle-31' OR g.status<>'in_progress' OR m.finished OR g.is_paused THEN RAISE EXCEPTION 'battle31:inactive';END IF;
 IF m.revision<>p_revision THEN RAISE EXCEPTION 'battle31:stale_revision';END IF;
 IF p_action<>'resign' AND actor_i<>(m.state->>'turnIndex')::int THEN RAISE EXCEPTION 'battle31:wrong_turn';END IF;
 IF p_action NOT IN('swap','take_pot','pass','resign','tick') THEN RAISE EXCEPTION 'battle31:invalid_action';END IF;
 at_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
 IF p_action='tick' AND at_ms<(m.state->>'deadline')::bigint THEN RETURN;END IF;
 m.state:=private.battle31_reduce(m.state,p_action,CASE WHEN p_action='resign' THEN ARRAY[actor_i] ELSE p_items END,at_ms);
 INSERT INTO private.battle31_requests VALUES(p_dealer,p_request,p_player,cmd);
 UPDATE private.battle31_matches SET state=m.state,revision=revision+1,bot_due_at=at_ms+750 WHERE dealer_game_id=p_dealer;
 IF m.state->>'phase'='complete' THEN PERFORM private.battle31_settle(p_dealer);END IF;
END $$;
CREATE OR REPLACE FUNCTION public.battle31_action(p_dealer_game_id uuid,p_request_id uuid,p_revision bigint,p_action text,p_items integer[] DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;
BEGIN
 IF NOT private.battle31_actor_allowed(auth.uid()) OR p_action IS NULL OR p_action NOT IN('swap','take_pot','pass','resign') THEN RAISE EXCEPTION 'battle31:forbidden' USING ERRCODE='42501';END IF;
 SELECT (p->>'id')::uuid INTO actor FROM private.battle31_matches m,jsonb_array_elements(m.state->'players') p WHERE m.dealer_game_id=p_dealer_game_id AND p->>'userId'=auth.uid()::text AND NOT (p->>'isBot')::boolean;
 IF actor IS NULL THEN RAISE EXCEPTION 'battle31:participant_required' USING ERRCODE='42501';END IF;
 PERFORM private.battle31_commit(p_dealer_game_id,p_request_id,p_revision,actor,p_action,p_items);
 RETURN public.battle31_snapshot(p_dealer_game_id);
END $$;
-- An integrity abort is an administrative operation, never a browser command.
CREATE OR REPLACE FUNCTION private.battle31_abort(p_dealer uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE m private.battle31_matches;
BEGIN
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer;
 PERFORM 1 FROM public.rounds WHERE id=m.round_id FOR UPDATE;
 PERFORM 1 FROM public.games WHERE id=m.game_id FOR UPDATE;
 SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=p_dealer FOR UPDATE;
 IF m.settlement IS NOT NULL THEN RETURN;END IF;
 UPDATE private.battle31_matches SET state=private.battle31_complete(state,'aborted',floor(extract(epoch FROM clock_timestamp())*1000)::bigint),revision=revision+1 WHERE dealer_game_id=p_dealer;
 PERFORM private.battle31_settle(p_dealer);
END $$;

CREATE OR REPLACE FUNCTION private.battle31_bot_choice(v jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE actor int:=(v->>'turnIndex')::int;opponent int:=1-actor;hand jsonb:=v->'hands'->actor;center jsonb:=v->'center';known jsonb:=v->'known'->opponent;samples jsonb;sample jsonb;candidate jsonb;newcenter jsonb;trial jsonb;value_i numeric;oppvalue numeric;utility numeric;best numeric:=-1e9;bestscore numeric:=-1;choice jsonb;option_i int;i int;j int;card_i int;action_i text;items_i jsonb;final_i boolean:=(v->>'closing')::boolean OR (v->>'turn')::int=8;
BEGIN
 IF hand @> '[null]'::jsonb THEN RAISE EXCEPTION 'battle31:bot_projection';END IF;
 -- Fixed bounded sample of possible hands. Input is the actor projection only.
 SELECT jsonb_agg(h) INTO samples FROM (SELECT jsonb_build_array(a,b,c) h FROM generate_series(0,31) a,generate_series(0,31) b,generate_series(0,31) c
 WHERE a<b AND b<c AND NOT hand @> to_jsonb(a) AND NOT hand @> to_jsonb(b) AND NOT hand @> to_jsonb(c)
 AND NOT center @> to_jsonb(a) AND NOT center @> to_jsonb(b) AND NOT center @> to_jsonb(c)
 AND jsonb_build_array(a,b,c) @> known ORDER BY md5(jsonb_build_array(a,b,c)::text||hand::text||center::text) LIMIT 16) possible;
 FOR option_i IN 0..10 LOOP
  candidate:=hand;newcenter:=center;items_i:=NULL;action_i:='pass';
  IF option_i=10 THEN candidate:=center;newcenter:=hand;action_i:='take_pot';
  ELSIF option_i>0 THEN i:=(option_i-1)/3;j:=(option_i-1)%3;candidate:=jsonb_set(hand,ARRAY[i::text],center->j);newcenter:=jsonb_set(center,ARRAY[j::text],hand->i);action_i:='swap';items_i:=jsonb_build_array(hand->i,center->j);END IF;
  value_i:=private.battle31_score(candidate);utility:=0;
  FOR sample IN SELECT value FROM jsonb_array_elements(samples) LOOP
   oppvalue:=private.battle31_score(sample);
   IF NOT final_i AND value_i<31 THEN
    oppvalue:=greatest(oppvalue,private.battle31_score(newcenter));
    FOR i IN 0..2 LOOP FOR j IN 0..2 LOOP trial:=jsonb_set(sample,ARRAY[i::text],newcenter->j);oppvalue:=greatest(oppvalue,private.battle31_score(trial));END LOOP;END LOOP;
   END IF;
   utility:=utility+CASE WHEN value_i>=31 THEN 1 ELSE sign(value_i-oppvalue) END;
  END LOOP;
  IF utility>best OR utility=best AND value_i>bestscore THEN best:=utility;bestscore:=value_i;choice:=jsonb_build_object('action',action_i,'items',items_i);END IF;
 END LOOP;
 RETURN choice;
END $$;

-- LockRows precedes LIMIT: locked sessions do not consume the 20-row budget.
-- Every selected row holds the round/session/match locks before calling the
-- existing command or postgame owner. No alternate reducer or settlement path.
CREATE OR REPLACE FUNCTION private.battle31_recover() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE candidate record; m private.battle31_matches; g public.games;
 actor uuid; choice jsonb; action_i text; items_i int[]; req uuid;
 at_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000);
BEGIN
 FOR candidate IN
  SELECT work.dealer_game_id,work.game_id,work.round_id,work.revision,
   work.state->>'dealId' deal_id,work.state->>'phase' phase,
   work.state->>'turnIndex' turn_index
  FROM public.rounds r
  JOIN public.games live ON live.id=r.game_id
  JOIN private.battle31_matches work ON work.round_id=r.id AND work.game_id=live.id AND work.dealer_game_id=r.dealer_game_id
  WHERE NOT work.finished AND work.settlement IS NULL AND work.paused_at IS NULL
   -- Lock every existing participant before the LIMIT as well. A busy player
   -- row must not repeatedly consume a slot and starve later sessions.
   AND (SELECT count(*) FROM (SELECT p.id FROM public.players p
        WHERE p.game_id=work.game_id FOR UPDATE SKIP LOCKED) claimed)
       =(SELECT count(*) FROM public.players p WHERE p.game_id=work.game_id)
   AND live.current_game_uuid=work.dealer_game_id AND live.game_type='battle-31'
   AND live.status='in_progress' AND NOT live.is_paused
   AND ((work.state->>'deadline')::bigint<=at_ms OR work.state->>'phase'='playing'
    AND coalesce(work.bot_due_at,0)<=at_ms
    AND (work.state->'players'->(work.state->>'turnIndex')::int->>'isBot')::boolean)
  ORDER BY (work.state->>'deadline')::bigint,work.dealer_game_id
  LIMIT 20 FOR UPDATE OF r,live,work SKIP LOCKED
 LOOP
  SELECT * INTO STRICT g FROM public.games WHERE id=candidate.game_id;
  SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=candidate.dealer_game_id;
  at_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
  IF g.current_game_uuid IS DISTINCT FROM m.dealer_game_id OR g.game_type IS DISTINCT FROM 'battle-31'
   OR g.status<>'in_progress' OR g.is_paused OR m.finished OR m.settlement IS NOT NULL OR m.paused_at IS NOT NULL
   OR m.game_id<>candidate.game_id OR m.round_id<>candidate.round_id OR m.revision<>candidate.revision
   OR m.state->>'dealId' IS DISTINCT FROM candidate.deal_id OR m.state->>'phase' IS DISTINCT FROM candidate.phase
   OR m.state->>'turnIndex' IS DISTINCT FROM candidate.turn_index THEN CONTINUE;END IF;
  actor:=(m.state->'players'->(m.state->>'turnIndex')::int->>'id')::uuid;items_i:=NULL;
  IF (m.state->>'deadline')::bigint<=at_ms THEN action_i:='tick';
  ELSIF m.state->>'phase'='playing' AND coalesce(m.bot_due_at,0)<=at_ms
   AND (m.state->'players'->(m.state->>'turnIndex')::int->>'isBot')::boolean
   AND EXISTS(SELECT 1 FROM public.players WHERE id=actor AND game_id=m.game_id AND is_bot) THEN
   choice:=private.battle31_bot_choice(private.battle31_visible(m.state,actor));action_i:=choice->>'action';
   SELECT array_agg(value::int) INTO items_i FROM jsonb_array_elements_text(coalesce(nullif(choice->'items','null'),'[]'));
  ELSE CONTINUE;END IF;
  req:=md5(m.dealer_game_id::text||':'||m.revision||':service')::uuid;
  BEGIN
   -- A player/accounting writer outside the normal session lock contract must
   -- not block the entire batch either. Release partial locks on NOWAIT failure.
   PERFORM 1 FROM public.players WHERE game_id=m.game_id ORDER BY id FOR UPDATE NOWAIT;
   PERFORM private.battle31_commit(m.dealer_game_id,req,m.revision,actor,action_i,items_i);
  EXCEPTION WHEN lock_not_available THEN CONTINUE;
   WHEN raise_exception THEN IF SQLERRM NOT IN('battle31:stale_revision','battle31:inactive','battle31:deadline') THEN RAISE;END IF;
  END;
 END LOOP;
 at_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
 FOR candidate IN
  SELECT work.dealer_game_id,work.game_id,work.round_id,work.revision
  FROM public.rounds r
  JOIN public.games live ON live.id=r.game_id
  JOIN private.battle31_matches work ON work.round_id=r.id AND work.game_id=live.id AND work.dealer_game_id=r.dealer_game_id
  WHERE NOT work.finished AND work.settlement IS NOT NULL
   AND (work.state#>>'{terminal,deadline}')::bigint<=at_ms
   -- Lock every existing participant before the LIMIT as well. A busy player
   -- row must not repeatedly consume a slot and starve later sessions.
   AND (SELECT count(*) FROM (SELECT p.id FROM public.players p
        WHERE p.game_id=work.game_id FOR UPDATE SKIP LOCKED) claimed)
       =(SELECT count(*) FROM public.players p WHERE p.game_id=work.game_id)
   AND live.current_game_uuid=work.dealer_game_id AND live.game_type='battle-31'
   AND live.status IN('game_over','session_ended') AND NOT live.is_paused
  ORDER BY (work.state#>>'{terminal,deadline}')::bigint,work.dealer_game_id
  LIMIT 20 FOR UPDATE OF r,live,work SKIP LOCKED
 LOOP
  SELECT * INTO STRICT g FROM public.games WHERE id=candidate.game_id;
  SELECT * INTO STRICT m FROM private.battle31_matches WHERE dealer_game_id=candidate.dealer_game_id;
  IF m.finished OR m.settlement IS NULL OR m.revision<>candidate.revision
   OR m.game_id<>candidate.game_id OR m.round_id<>candidate.round_id
   OR g.current_game_uuid IS DISTINCT FROM m.dealer_game_id OR g.game_type IS DISTINCT FROM 'battle-31'
   OR g.status NOT IN('game_over','session_ended') OR g.is_paused THEN CONTINUE;END IF;
  BEGIN
   PERFORM 1 FROM public.players WHERE game_id=m.game_id ORDER BY id FOR UPDATE NOWAIT;
   PERFORM private.battle31_finish_postgame(m.dealer_game_id);
  EXCEPTION WHEN lock_not_available THEN CONTINUE;
  END;
 END LOOP;
END $$;

-- Extend the inspected current Boxdrop registration; guard deployed hashes before applying.
CREATE OR REPLACE FUNCTION private.megatouch_begin(p_game uuid, p_dealer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE g public.games;dg public.dealer_games;r uuid:=gen_random_uuid();people jsonb;balances jsonb;s jsonb;stake_i integer;
BEGIN
 SELECT * INTO STRICT g FROM public.games WHERE id=p_game FOR UPDATE;
 SELECT * INTO STRICT dg FROM public.dealer_games WHERE id=p_dealer AND session_id=p_game;
 IF g.current_game_uuid IS DISTINCT FROM p_dealer OR g.status<>'ante_decision' OR g.game_type NOT IN('eleven-up','tri-towers','run21','royal-flash','take-two','trip-flip','boxdrop','race-poker','battle-31') OR g.is_paused THEN RAISE EXCEPTION 'megatouch:ante_identity';END IF;
 stake_i:=(dg.config->>'ante_amount')::integer;
 IF g.ante_amount IS DISTINCT FROM stake_i THEN RAISE EXCEPTION 'megatouch:stake_changed';END IF;
 PERFORM 1 FROM public.players WHERE game_id=p_game ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.players WHERE game_id=p_game AND status='active' AND NOT sitting_out AND NOT waiting AND position IS NOT NULL AND ante_decision IS NULL) THEN RAISE EXCEPTION 'megatouch:acceptance_pending';END IF;
 SELECT jsonb_agg(jsonb_build_object('id',p.id,'userId',p.user_id,'name',coalesce(pr.username,'Player'),'seat',p.position,'isBot',p.is_bot,'kind',CASE WHEN p.is_bot THEN 'bot' ELSE 'human' END,'chips',p.chips)
 ORDER BY CASE WHEN g.game_type='run21' THEN 0 WHEN p.position<g.dealer_position THEN 0 ELSE 1 END,CASE WHEN g.game_type='run21' THEN p.position ELSE -p.position END,p.id),jsonb_object_agg(p.id,p.chips)
 INTO people,balances FROM public.players p JOIN public.profiles pr ON pr.id=p.user_id
 WHERE p.game_id=p_game AND p.status='active' AND NOT p.sitting_out AND NOT p.waiting AND p.position IS NOT NULL AND p.ante_decision='ante_up';
 IF coalesce(jsonb_array_length(people),0)<2 OR jsonb_array_length(people)>(CASE WHEN g.game_type IN('run21','trip-flip','boxdrop','race-poker','battle-31') THEN 2 ELSE 7 END) THEN RAISE EXCEPTION 'megatouch:accepted_player_count';END IF;
 IF g.game_type='eleven-up' AND EXISTS(SELECT 1 FROM jsonb_array_elements(people)p WHERE (p->>'isBot')::boolean) THEN RAISE EXCEPTION 'eleven_up:bots_not_supported';END IF;
 PERFORM set_config('app.cribbage_authoritative_write','on',true);PERFORM set_config('app.gin_rummy_authoritative_write','on',true);PERFORM set_config('app.three_five_seven_authoritative_write','on',true);PERFORM set_config('app.yahtzee_authoritative_write','on',true);
 UPDATE public.games SET status='in_progress',ante_decision_deadline=NULL,current_round=1,total_hands=1 WHERE id=p_game;
 INSERT INTO public.rounds(id,game_id,dealer_game_id,hand_number,round_number,cards_dealt,status,pot) VALUES(r,p_game,p_dealer,1,1,0,'betting',0);
 IF g.game_type='run21' THEN
  INSERT INTO private.run21_matches(dealer_game_id,game_id,first_round_id,participants,stake,initial_balances,balances,financial_version,real_money,first_placement_seconds)
  VALUES(p_dealer,p_game,r,people,stake_i,balances,balances,2,g.real_money,(dg.config->>'first_placement_seconds')::integer);
 ELSE
  s:=jsonb_build_object('identity',jsonb_build_object('sessionId',p_game,'dealerGameId',p_dealer,'roundId',r),'players',people,'rules',dg.config->'rules','turnIndex',0,'stage',1,'score',0,'scores','{}'::jsonb,'stages','[]'::jsonb);
  IF g.game_type='battle-31' THEN
   s:=private.battle31_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.battle31_matches(dealer_game_id,game_id,round_id,state,stake) VALUES(p_dealer,p_game,r,s,stake_i);
  ELSIF g.game_type='race-poker' THEN
   IF NOT EXISTS(SELECT 1 FROM private.race_poker_release WHERE singleton AND enabled AND admission_enabled AND CASE WHEN g.real_money THEN real_qualified ELSE fake_qualified END) THEN RAISE EXCEPTION 'race_poker:admission_closed';END IF;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(people)p WHERE NOT (p->>'isBot')::boolean) THEN RAISE EXCEPTION 'race_poker:human_required';END IF;
   s:=private.race_poker_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.race_poker_matches(dealer_game_id,game_id,round_id,state,stake,real_money) VALUES(p_dealer,p_game,r,s,stake_i,g.real_money);
  ELSIF g.game_type='boxdrop' THEN
   s:=private.boxdrop_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.boxdrop_matches(dealer_game_id,game_id,round_id,state,stake) VALUES(p_dealer,p_game,r,s,stake_i);
  ELSIF g.game_type='trip-flip' THEN
   s:=private.trip_flip_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.trip_flip_matches(dealer_game_id,game_id,round_id,state,stake) VALUES(p_dealer,p_game,r,s,stake_i);
  ELSIF g.game_type='take-two' THEN
   s:=private.take_two_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.take_two_matches(dealer_game_id,game_id,round_id,state,stake) VALUES(p_dealer,p_game,r,s,stake_i);
  ELSIF g.game_type='royal-flash' THEN
   s:=private.royal_flash_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.royal_flash_matches(dealer_game_id,game_id,round_id,state,stake) VALUES(p_dealer,p_game,r,s,stake_i);
  ELSIF g.game_type='eleven-up' THEN
   s:=private.eleven_up_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.eleven_up_matches(dealer_game_id,game_id,round_id,state,stake) VALUES(p_dealer,p_game,r,s,stake_i);
  ELSE
   s:=private.tri_towers_deal(s,floor(extract(epoch FROM clock_timestamp())*1000)::bigint);
   INSERT INTO private.tri_towers_matches(dealer_game_id,game_id,round_id,state,stake) VALUES(p_dealer,p_game,r,s,stake_i);
  END IF;
 END IF;
 RETURN jsonb_build_object('dealerGameId',p_dealer,'roundId',r);
END $function$
;
CREATE OR REPLACE FUNCTION private.advance_ante_phase_exact(p_game_id uuid, p_expected_dealer_game_id uuid, p_expected_deadline timestamp with time zone, p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_prior_farkle_claim text:=coalesce(current_setting('app.farkle_authority',true),''); v_replay_shared jsonb; v_replay_return jsonb;
  v_game public.games%ROWTYPE;
  v_unresolved integer;
  v_anted integer;
  v_outcome text;
  v_start jsonb;
BEGIN
  SELECT * INTO v_game FROM public.games WHERE id=p_game_id FOR UPDATE;
 IF FOUND THEN
  IF v_game.replay_contract_version=1 THEN v_replay_shared:=private.replay_gin_lifecycle_begin_v2(v_game,'private.advance_ante_phase_exact',false,jsonb_build_object('p_game_id',p_game_id,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_deadline',p_expected_deadline,'p_now',p_now)); END IF;
  PERFORM 1; -- Preserve the original missing-row guard.
 END IF;
  IF NOT FOUND THEN v_replay_return := jsonb_build_object('outcome','missing_game');
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_deadline',p_expected_deadline,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return; END IF;
  IF v_game.status IS DISTINCT FROM 'ante_decision'
     OR v_game.current_game_uuid IS DISTINCT FROM p_expected_dealer_game_id
     OR v_game.ante_decision_deadline IS DISTINCT FROM p_expected_deadline THEN
    v_replay_return := jsonb_build_object('outcome','stale_identity','status',v_game.status);
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_deadline',p_expected_deadline,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return;
  END IF;
  IF coalesce(v_game.is_paused,false) THEN
    v_replay_return := jsonb_build_object('outcome','paused');
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_deadline',p_expected_deadline,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return;
  END IF;

  IF v_game.game_type='farkle' THEN PERFORM private.farkle_claim_v1(v_game.id,v_game.current_game_uuid,NULL,'start'); END IF;
  UPDATE public.players player
     SET ante_decision='ante_up',sitting_out=false
   WHERE player.game_id=p_game_id
     AND coalesce(player.is_bot,false)
     AND NOT coalesce(player.sitting_out,false)
     AND player.status NOT IN ('observer','left')
     AND player.ante_decision IS NULL;

  UPDATE public.players player
     SET sitting_out=true,waiting=false
   WHERE player.game_id=p_game_id
     AND player.ante_decision='sit_out'
     AND NOT coalesce(player.sitting_out,false);

  IF p_expected_deadline<=p_now THEN
    UPDATE public.players player
       SET ante_decision='sit_out',sitting_out=true,waiting=false
     WHERE player.game_id=p_game_id
       AND NOT coalesce(player.is_bot,false)
       AND NOT coalesce(player.sitting_out,false)
       AND player.status NOT IN ('observer','left')
       AND player.ante_decision IS NULL;
  END IF;

  SELECT count(*) INTO v_unresolved
    FROM public.players player
   WHERE player.game_id=p_game_id
     AND NOT coalesce(player.sitting_out,false)
     AND player.status NOT IN ('observer','left')
     AND player.position IS NOT NULL
     AND player.ante_decision IS NULL;
  IF v_unresolved>0 THEN
    v_replay_return := jsonb_build_object(
      'outcome','pending','unresolved',v_unresolved,
      'deadline',p_expected_deadline
    );
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_deadline',p_expected_deadline,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return;
  END IF;

  UPDATE public.players player
     SET sitting_out_hands=CASE
           WHEN coalesce(player.sitting_out,false)
             THEN coalesce(player.sitting_out_hands,0)+1
           ELSE 0 END
   WHERE player.game_id=p_game_id
     AND player.status NOT IN ('observer','left');

  SELECT count(*) INTO v_anted
    FROM public.players player
   WHERE player.game_id=p_game_id
     AND NOT coalesce(player.sitting_out,false)
     AND player.status NOT IN ('observer','left')
     AND player.position IS NOT NULL
     AND player.ante_decision='ante_up';

  -- Both the not-enough-players disposition and normal game bootstrap are
  -- private database-owned transitions. Establish the existing trusted local
  -- claim before either branch so a fresh authenticated HTTP request does not
  -- depend on dealer setup's expired transaction-local authority flags.
  PERFORM set_config('request.jwt.claim.role','service_role',true);
  PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);

  IF v_anted<2 THEN
    IF coalesce(v_game.real_money,false) THEN
      v_outcome:=private.resolve_postgame_participation(p_game_id,p_now);
    ELSE
      UPDATE public.games
         SET status='waiting',current_game_uuid=NULL,config_complete=false,
             config_deadline=NULL,ante_decision_deadline=NULL,
             awaiting_next_round=false,last_round_result=NULL
       WHERE id=p_game_id;
      v_outcome:='waiting-not-enough-players';
    END IF;
    v_replay_return := jsonb_build_object('outcome','not_enough_players','reason',v_outcome);
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_deadline',p_expected_deadline,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return;
  END IF;

  CASE
    WHEN v_game.game_type IN ('3-5-7','3-5-7-game','357') THEN
      SELECT public.three_five_seven_begin_game(p_game_id) INTO v_start;
    WHEN v_game.game_type IN ('holm','holm-game') THEN
      SELECT public.start_holm_initial_hand(p_game_id,false) INTO v_start;
    WHEN v_game.game_type='cribbage' THEN
      SELECT public.cribbage_begin_dealer_selection(p_game_id) INTO v_start;
    WHEN v_game.game_type='gin-rummy' THEN
      SELECT public.start_gin_rummy_initial_hand(p_game_id) INTO v_start;
    WHEN v_game.game_type IN ('eleven-up','tri-towers','run21','royal-flash','take-two','trip-flip','boxdrop','race-poker','battle-31') THEN
      SELECT private.megatouch_begin(p_game_id,p_expected_dealer_game_id) INTO v_start;
    WHEN v_game.game_type='farkle' THEN
      SELECT private.farkle_begin_v1(p_game_id,p_expected_dealer_game_id) INTO v_start;
    WHEN v_game.game_type='yahtzee' THEN
      SELECT public.start_yahtzee_round(p_game_id,NULL) INTO v_start;
    WHEN v_game.game_type IN ('horses','ship-captain-crew') THEN
      SELECT private.start_horses_scc_initial_round(
        p_game_id,p_expected_dealer_game_id
      ) INTO v_start;
    ELSE
      RAISE EXCEPTION 'advance_ante_phase_exact:unsupported_game_type:%',v_game.game_type;
  END CASE;

  v_replay_return := jsonb_build_object(
    'outcome','advanced','game_type',v_game.game_type,'start',v_start
  );
 IF v_replay_shared IS NOT NULL THEN PERFORM private.replay_gin_shared_end_v1(v_replay_shared,jsonb_build_object('p_game_id',p_game_id,'p_expected_dealer_game_id',p_expected_dealer_game_id,'p_expected_deadline',p_expected_deadline,'p_now',p_now),to_jsonb(v_replay_return)); END IF;
 PERFORM set_config('app.farkle_authority',v_prior_farkle_claim,true); RETURN v_replay_return;
END;
$function$
;
CREATE OR REPLACE FUNCTION private.megatouch_frozen_stake()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF OLD.game_type IN('eleven-up','tri-towers','run21','royal-flash','take-two','trip-flip','boxdrop','race-poker','battle-31') AND NEW.config IS DISTINCT FROM OLD.config THEN RAISE EXCEPTION 'megatouch:configuration_frozen';END IF;RETURN NEW;
END $function$
;

-- Explicit grants only. All raw state/decks/helpers remain private.
DO $$ DECLARE f record;BEGIN
 FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('private','public') AND p.proname LIKE 'battle31_%' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f.signature);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION public.battle31_capabilities(uuid),public.battle31_snapshot(uuid),public.battle31_configure(uuid,uuid,integer,text,jsonb,timestamptz),public.battle31_close(uuid) TO authenticated;

-- Acquire shared-table locks last. NOWAIT never queues behind live writes.
LOCK TABLE public.games,public.dealer_games,public.rounds IN SHARE ROW EXCLUSIVE MODE NOWAIT;
ALTER TABLE private.battle31_matches
 ADD FOREIGN KEY(dealer_game_id) REFERENCES public.dealer_games(id) ON DELETE CASCADE,
 ADD FOREIGN KEY(game_id) REFERENCES public.games(id) ON DELETE CASCADE,
 ADD FOREIGN KEY(round_id) REFERENCES public.rounds(id) ON DELETE CASCADE;
ALTER TABLE public.battle31_revisions ADD FOREIGN KEY(game_id) REFERENCES public.games(id) ON DELETE CASCADE;
CREATE TRIGGER battle31_pause AFTER UPDATE OF is_paused ON public.games FOR EACH ROW
 WHEN(NEW.game_type='battle-31') EXECUTE FUNCTION private.battle31_pause();

CREATE TRIGGER battle31_publish AFTER INSERT OR UPDATE ON private.battle31_matches FOR EACH ROW EXECUTE FUNCTION private.battle31_publish();

GRANT EXECUTE ON FUNCTION public.battle31_action(uuid,uuid,bigint,text,integer[]) TO authenticated;

-- Closed-admission registration. Run only inside the guarded release package.
DO $registration$
DECLARE job record; command_i text:='SET statement_timeout=''3s''; SELECT private.battle31_recover()';
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime')
  OR to_regprocedure('cron.schedule(text,text,text)') IS NULL THEN RAISE EXCEPTION 'battle31:platform_registration_missing';END IF;
 IF EXISTS(SELECT 1 FROM cron.job WHERE jobname='battle31-recovery') THEN
  IF (SELECT count(*) FROM cron.job WHERE jobname='battle31-recovery')<>1 THEN RAISE EXCEPTION 'battle31:scheduler_collision';END IF;
  SELECT * INTO STRICT job FROM cron.job WHERE jobname='battle31-recovery';
  IF job.schedule IS DISTINCT FROM '1 second' OR job.command IS DISTINCT FROM command_i
   OR job.database IS DISTINCT FROM current_database() OR job.username IS DISTINCT FROM current_user OR job.active IS DISTINCT FROM true THEN RAISE EXCEPTION 'battle31:scheduler_collision';END IF;
 ELSE
  PERFORM cron.schedule('battle31-recovery','1 second',command_i);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='battle31_revisions') THEN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.battle31_revisions;
 END IF;
END $registration$;
INSERT INTO public.game_defaults(game_type,presentation_mode,ante_amount,real_money,debug_harness,timeout_action,timeout_enforcement_enabled,pot_max_enabled,pussy_tax_enabled,leg_value,legs_to_win)
 VALUES('battle-31','fullscreen',5,false,'none','none',false,false,false,0,0) ON CONFLICT(game_type) DO NOTHING;
-- No admission activation statement belongs in this candidate.
$battle31_payload$;
 IF EXISTS(SELECT 1 FROM private.battle31_release WHERE enabled OR admission_enabled) THEN RAISE EXCEPTION 'battle31:admission_must_be_closed';END IF;
 SELECT jsonb_build_object(
 'functions',(SELECT jsonb_object_agg(p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid)||coalesce(p.proacl::text,''))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('private','public') AND (p.proname LIKE 'battle31_%' OR p.oid=ANY(ARRAY['private.megatouch_begin(uuid,uuid)'::regprocedure,'private.advance_ante_phase_exact(uuid,uuid,timestamptz,timestamptz)'::regprocedure,'private.megatouch_frozen_stake()'::regprocedure,'public.settle_gameplay_chip_transfers(uuid,jsonb,text)'::regprocedure,'public.submit_ante_decision(uuid,uuid,uuid,text,boolean,boolean)'::regprocedure]))),
 'tables',(SELECT jsonb_object_agg(n.nspname||'.'||r.relname,jsonb_build_object('rls',r.relrowsecurity,'acl',r.relacl::text,
  'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,a.atttypid::regtype::text,a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped),
  'constraints',(SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid=r.oid),
  'indexes',(SELECT jsonb_agg(pg_get_indexdef(indexrelid) ORDER BY indexrelid::regclass::text) FROM pg_index WHERE indrelid=r.oid),
  'policies',(SELECT jsonb_agg(jsonb_build_array(polname,polcmd,polroles::text,pg_get_expr(polqual,polrelid),pg_get_expr(polwithcheck,polrelid)) ORDER BY polname) FROM pg_policy WHERE polrelid=r.oid),
  'triggers',(SELECT jsonb_agg(pg_get_triggerdef(oid) ORDER BY tgname) FROM pg_trigger WHERE tgrelid=r.oid AND NOT tgisinternal))) FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname IN('private','public') AND r.relkind='r' AND r.relname LIKE 'battle31_%'),
 'sharedTriggers',(SELECT jsonb_agg(pg_get_triggerdef(oid) ORDER BY tgname) FROM pg_trigger WHERE tgname LIKE 'battle31_%'),
 'publication',(SELECT count(*) FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='battle31_revisions'),
 'scheduler',(SELECT jsonb_agg(jsonb_build_array(schedule,command,database,username,active) ORDER BY jobid) FROM cron.job WHERE jobname='battle31-recovery')) INTO actual;
 EXECUTE format('COMMENT ON TABLE private.battle31_release IS %L',jsonb_build_object('sourceSHA256','9661335b5dd1969a0b49dbe380f02f74f4f000a6a88c7176ad10568e6223d3e9','main','0d9469ecc24345175b3cb07052d16283a1c4f42c','manifest',actual)::text);
END $battle31_release_package$;
